    /*
     * Assign a Organization
     * 
     * @param	parentId	UUID
     * @param	assignment 	Organization 
     * @return	Contact
     */
    public Contact assignOrganization( UUID parentId, Organization assignment ) {
	    LOGGER.info("assigning Organization as " + assignment.toString() );

	    Contact parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Organization.class, assignment.getOrganizationId());

	    // ------------------------------------------
		// assign the Organization to the parent entity
		// ------------------------------------------ 
	    parentEntity.setOrganization( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Organization
	 * 
	 * @param	parentId		UUID
	 * @return	Contact
	 */
	public Contact unAssignOrganization( UUID parentId ) {
		Contact parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Organization on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Organization on the parent entithy
		// ------------------------------------------     
	    parentEntity.setOrganization(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}

