    /**
     * Method to retrieve the Contact via an FindContactQuery
     * @return 	query	FindContactQuery
     */
    @SuppressWarnings("unused")
    public Contact find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Contact - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Contacts
     *
     * @param	query	FindAllContactQuery 
     * @return 	List<Contact> 
     */
    @SuppressWarnings("unused")
    public List<Contact> findAll( FindAllContactQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Contact - {0}", exc.getMessage() );
    	}
    	return null;
    }


